mapper.select:
SELECT FROM inquiry WHERE buyer_tenant_id = #{tenantId} AND is_deleted = 0
AND (title LIKE CONCAT('%', #{keyword}, '%') OR category LIKE CONCAT('%', #{keyword}, '%') OR inquiry_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY create_time DESC LIMIT #{offset}, #{limit}

SELECT FROM inquiry i INNER JOIN inquiry_invite inv ON inv.inquiry_id = i.id AND inv.supplier_tenant_id = #{tenantId} AND inv.is_deleted = 0 WHERE i.is_deleted = 0
AND (i.title LIKE CONCAT('%', #{keyword}, '%') OR i.category LIKE CONCAT('%', #{keyword}, '%') OR i.inquiry_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY i.create_time DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE inquiry
SET status = #{status}, update_by = #{updateBy}
WHERE id = #{id} AND buyer_tenant_id = #{tenantId} AND is_deleted = 0

UPDATE inquiry
title = #{title}, category = #{category}, quantity = #{quantity}, unit = #{unit}, delivery_place = #{deliveryPlace}, delivery_date = #{deliveryDate}, payment_terms = #{paymentTerms}, spec_text = #{specText}, update_by = #{updateBy}
WHERE id = #{id} AND buyer_tenant_id = #{buyerTenantId} AND status = 'open' AND is_deleted = 0
